 * that has dropped keeps the slot it had just before, so it fades where it sat.
 */
function slotOf(key: CardKey, typed: number) {
  const at = key === "receipt" ? typed : Math.min(typed, CARDS[key].drop - 1);
  const row = ROWS.findIndex((cards) => (cards as readonly CardKey[]).includes(key));
  const col = ROWS[row]
    .slice(0, ROWS[row].indexOf(key as never))
    .filter((other) => stillMatches(other, at)).length;
  return { x: col * (THUMB_W + GAP), y: GRID_TOP + row * (THUMB_H + GAP) };
