export function pdfPreviewTitle(value: string): string {
  return value
    .replace(/\uFFFD/gu, "’")
    .replace(/\.[^.]+$/u, "")
    .replace(/[-_]+/gu, " ")
    .replace(/\s+/gu, " ")
    .trim();
}

