1	import { useEffect, useState, type CSSProperties } from "react";
2	import { InklingMascot } from "../mascot/InklingMascot";
3	import { prefersReducedMotion } from "../mascot/mascotStore";
4	
5	/** How long each face holds before the next one glides in. */
6	const FACE_HOLD_MS = 3400;
7	
8	/**
9	 * The large, cropped mascot on the first and last welcome screens. It drifts
10	 * and blinks like the sidebar one, and wanders through a few calm faces. It
11	 * owns its own engine, so the library's mascot keeps its clock and its face.
12	 */
13	export function OnboardingMascot({
14	  size,
15	  faces,
16	  look,
17	  speed = 1,
18	  style,
19	}: {
20	  size: number;
21	  faces: readonly string[];
22	  /** Where the eyes stay pointed (toward the screen's text) through every face. */
23	  look: { yaw: number; pitch: number };
24	  /** Playback rate of the animation and the face changes (1 = normal). */
25	  speed?: number;
26	  style?: CSSProperties;
27	}) {
28	  const [reduced] = useState(prefersReducedMotion);
29	  const [faceIndex, setFaceIndex] = useState(0);
30	
31	  useEffect(() => {
32	    if (reduced || faces.length < 2) return;
33	    const timer = window.setInterval(
34	      () => setFaceIndex((index) => (index + 1) % faces.length),
35	      FACE_HOLD_MS / speed,
36	    );
37	    return () => window.clearInterval(timer);
38	  }, [faces, reduced, speed]);
39	
40	  return (
41	    <div className="first-run-mascot" style={style} aria-hidden="true">
42	      <InklingMascot
43	        size={size}
44	        state="inkling-drift-faced"
45	        expression={faces[faceIndex]}
46	        ink="#2b2623"
47	        paper="#e5ddd2"
48	        playing={!reduced}
49	        look={look}
50	        speed={speed}
51	      />
52	    </div>
53	  );
54	}
