.first-run-overlay {
  position: fixed;
  inset: 0;
  z-index: 120;
  overflow: hidden;
  background: var(--library-canvas);
  color: var(--library-text);
  font-family: ui-sans-serif, system-ui, sans-serif;
}
.first-run-stage {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 960px;
  height: 540px;
  transform-origin: center;
}
/* One type and control scale for every welcome screen, in stage pixels. The
   stage itself scales with the window (FirstRunOverlay), so these never do. */
.first-run-stage {
  --fr-headline: 68px;
  --fr-body: 21px;
  --fr-small: 15px;
  --fr-button-h: 54px;
  --fr-button: 19px;
  --fr-quiet: 18px;
}
.first-run-headline {
  position: absolute;
  margin: 0;
  font-size: var(--fr-headline);
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 1.05;
  white-space: nowrap;
}
.first-run-body {
  position: absolute;
  margin: 0;
  font-size: var(--fr-body);
  line-height: 1.55;
  color: var(--library-muted);
  white-space: nowrap;
}
.first-run-headline.is-wrapped {
  white-space: normal;
}
/* SplitText's inline-block words would otherwise sit on the baseline and
   open up taller lines mid-animation than the reverted text has. */
.first-run-headline div {
  vertical-align: top;
}
.first-run-headline.is-centered,
.first-run-body.is-centered {
  left: 0;
  right: 0;
  text-align: center;
}
.first-run-keys {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-ui);
  font-size: var(--fr-small);
  color: var(--library-muted);
}
