const { app, BrowserWindow } = require("electron");
const fs = require("fs");
const [W, H] = (process.env.SIZE || "1280x800").split("x").map(Number);
const URL = process.env.URL || "http://localhost:5173/";
const OUT = process.env.OUT || "C:/Users/chris/AppData/Local/Temp/agents/chat-images/onboarding-scale/";
const TAG = process.env.TAG || "";
fs.mkdirSync(OUT, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
app.whenReady().then(async () => {
  const w = new BrowserWindow({
    width: W,
    height: H,
    show: true,
    useContentSize: true,
    webPreferences: { backgroundThrottling: false },
  });
  await w.loadURL(URL);
  const js = (c) => w.webContents.executeJavaScript(c);
  const click = (sel, text) =>
    js(
      `(()=>{const e=[...document.querySelectorAll(${JSON.stringify(sel)})].find(e=>!${JSON.stringify(text)}||e.textContent.trim().startsWith(${JSON.stringify(text)}));if(e)e.click();return !!e})()`,
    );
  // Text boxes (actual glyph line rects) vs every visual block on the stage.
  const MEASURE = `(()=>{
    const rect=e=>{const b=e.getBoundingClientRect();return [b.left,b.top,b.right,b.bottom]};
    const lines=[...document.querySelectorAll('.first-run-headline,.first-run-body,.first-run-keys,.first-run-actions button,.first-run-crumb')].flatMap(e=>{const g=document.createRange();g.selectNodeContents(e);return [...g.getClientRects()].filter(x=>x.width>2).map(x=>[e.className.split(' ')[0]+':'+e.textContent.trim().slice(0,12),[x.left,x.top,x.right,x.bottom]])});
    const blocks=[...document.querySelectorAll('.kept-card,.memory-card,.memory-slot,.memory-found,.reads-search,.reads-receipt,.reads-card,.first-run-mascot svg')].map(e=>[e.className.baseVal!==undefined?'svg':e.className,rect(e)]);
    const hit=(a,b)=>a[0]<b[2]-1&&a[2]>b[0]+1&&a[1]<b[3]-1&&a[3]>b[1]+1;
    const ov=[];blocks.forEach(([n,b])=>{if(n==='svg')return;lines.forEach(([t,l])=>{if(hit(b,l))ov.push(n.replace(/ is-\\w+/g,'').trim()+' x '+t)})});
    const off=[];lines.forEach(([t,l])=>{if(l[0]<0||l[1]<0||l[2]>innerWidth||l[3]>innerHeight)off.push(t)});
    const hl=[...document.querySelectorAll('.first-run-headline')].map(e=>Math.round(parseFloat(getComputedStyle(e).fontSize)*new DOMMatrix(getComputedStyle(document.querySelector('.first-run-stage')).transform).a));
    const btn=[...document.querySelectorAll('.first-run-actions button')].map(e=>{const b=e.getBoundingClientRect();return e.textContent.trim()+':'+Math.round(b.width)+'x'+Math.round(b.height)});
    return JSON.stringify({headlinePx:hl,btn,ov:[...new Set(ov)],off});
  })()`;
  const shot = async (name) => {
    fs.writeFileSync(OUT + `${TAG}${W}x${H}-${name}.png`, (await w.webContents.capturePage()).toPNG());
  };
  await sleep(2500);
  await click('[aria-label="Settings"]');
  await sleep(500);
  await click(".settings-tab", "General");
  await sleep(300);
  await click(".settings-data-button", "Show the welcome");
  const plan = JSON.parse(process.env.PLAN || "[[3000,4000],[3500],[2300,7500],[7500],[3000]]");
  for (let s = 0; s < 5; s++) {
    const t0 = Date.now();
    for (const at of plan[s]) {
      const d = at - (Date.now() - t0);
      if (d > 0) await sleep(d);
      await shot(`s${s + 1}-${at}`);
      console.log(`s${s + 1}@${at}`, await js(MEASURE));
    }
    if (s < 4) {
      await click(".first-run-primary", "Continue");
      if (process.env.MID) {
        await sleep(160);
        await shot(`s${s + 1}-leaving`);
        await sleep(400);
        await shot(`s${s + 2}-arriving`);
      }
    }
  }
  app.quit();
});

