const { app, BrowserWindow } = require("electron");
const fs = require("fs");
const path = require("path");
const [W, H] = (process.env.SIZE || "1280x720").split("x").map(Number);
const URL = process.env.URL || "http://localhost:5173/";
const DIR = process.env.DIR || "C:/Users/chris/AppData/Local/Temp/inkling-mascot/rec/";
fs.rmSync(DIR, { recursive: true, force: true });
fs.mkdirSync(DIR, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
app.whenReady().then(async () => {
  const w = new BrowserWindow({
    width: W,
    height: H,
    show: true,
    useContentSize: true,
    webPreferences: { backgroundThrottling: false },
  });
  await w.loadURL(URL);
  const js = (c) => w.webContents.executeJavaScript(c);
  const click = (sel, text) =>
    js(
      `(()=>{const e=[...document.querySelectorAll(${JSON.stringify(sel)})].find(e=>!${JSON.stringify(text)}||e.textContent.trim().startsWith(${JSON.stringify(text)}));if(e)e.click();return !!e})()`,
    );
  await sleep(2500);
  await click('[aria-label="Settings"]');
  await sleep(500);
  await click(".settings-tab", "General");
  await sleep(300);
  const frames = [];
  let recording = true;
  w.webContents.beginFrameSubscription(false, (image) => {
    if (!recording) return;
    const name = `f${String(frames.length).padStart(5, "0")}.jpg`;
    frames.push([name, performance.now()]);
    fs.writeFile(path.join(DIR, name), image.resize({ width: W, height: H }).toJPEG(88), () => {});
  });
  await click(".settings-data-button", "Show the welcome");
  // Drift the pointer slowly on the orbit screen so the parallax shows.
  const steps = [
    [3800, "Continue"],
    [6500, "Continue"],
    [7600, "Continue"],
    [7600, "Continue"],
    [3200, "Back"],
    [2600, "Continue"],
    [3600, null],
  ];
  for (const [hold, button] of steps) {
    const t0 = Date.now();
    while (Date.now() - t0 < hold) {
      const p = (Date.now() - t0) / hold;
      w.webContents.sendInputEvent({
        type: "mouseMove",
        x: Math.round(W * (0.35 + 0.3 * p)),
        y: Math.round(H * (0.4 + 0.2 * Math.sin(p * Math.PI))),
      });
      await sleep(50);
    }
    if (button === "Back") await click(".first-run-quiet", "Back");
    else if (button) await click(".first-run-primary", "");
  }
  await click(".first-run-primary", "Open my library");
  await sleep(1200);
  recording = false;
  w.webContents.endFrameSubscription();
  await sleep(500);
  const list = frames
    .map(([name, t], i) => {
      const next = frames[i + 1] ? frames[i + 1][1] : t + 33;
      return `file '${name}'\nduration ${((next - t) / 1000).toFixed(4)}`;
    })
    .join("\n");
  fs.writeFileSync(path.join(DIR, "list.txt"), list + `\nfile '${frames[frames.length - 1][0]}'\n`);
  console.log("frames", frames.length);
  app.quit();
});
